//! AG-3D-01 Squash the Creeps fidelity contract tests (T-06).
//!
//! The headline case replays the FROZEN independent reference trace
//! (`testdata/squash/golden_squash_trace.json`, generated by
//! `gen_squash_golden.py` from the frozen Mob.gd/Main.gd/Player.gd) through
//! the Rust implementation and compares positions (manifest tolerance 1e-2,
//! measured bit-exact), per-tick score/alive/mobs_alive, and the exact event
//! sequence (91 events: 45 spawns, 3 squashes, 1 death, 42 despawns;
//! re-frozen 2026-10-21 review r6 F829-R6-01 — source spawn height y=0).

use agp::core::runtime::Runtime;
use agp::games::squash::*;
use serde::Deserialize;
use std::path::PathBuf;
use std::time::Duration;

const POS_TOL: f32 = 1.0e-2;

fn trace_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("testdata/squash/golden_squash_trace.json")
}

#[derive(Debug, Deserialize)]
struct TraceTick {
    t: u64,
    px: f32,
    py: f32,
    pz: f32,
    vy: f32,
    score: u32,
    alive: u32,
    mobs_alive: u32,
}

#[derive(Debug, Deserialize)]
struct TraceEvent {
    t: u64,
    kind: String,
    index: Option<u32>,
    #[serde(default)]
    score: Option<u32>,
}

#[derive(Debug, Deserialize)]
struct SpawnRec {
    index: u32,
    tick: u64,
    pos: [f32; 3],
    yaw: f32,
    speed: f32,
    vel: [f32; 2],
}

#[derive(Debug, Deserialize)]
struct GoldenTrace {
    ticks_trace: Vec<TraceTick>,
    events: Vec<TraceEvent>,
    actions: Vec<[i8; 3]>,
    spawns: Vec<SpawnRec>,
}

fn load_trace() -> GoldenTrace {
    let bytes = std::fs::read(trace_path()).expect("frozen squash trace exists");
    serde_json::from_slice(&bytes).expect("trace parses")
}

fn action_of(a: [i8; 3]) -> SquashAction {
    SquashAction {
        move_x: a[0],
        move_z: a[1],
        jump: a[2] != 0,
        retry: false,
        reset: false,
    }
}

#[test]
fn golden_trace_replay_matches_reference() {
    let doc = load_trace();
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut driver = SquashDriver::new(SQUASH_SEED);
    let mut max_pos: f32 = 0.0;
    let mut events: Vec<(u64, SquashEvent)> = Vec::new();

    for (i, a) in doc.actions.iter().enumerate() {
        let step_events = rt.step(&mut driver, vec![action_of(*a)]);
        for e in step_events {
            events.push((i as u64, e.payload));
        }
        let want = &doc.ticks_trace[i];
        assert_eq!(want.t, i as u64);
        let d = (driver.player.x - want.px)
            .abs()
            .max((driver.player.y - want.py).abs())
            .max((driver.player.z - want.pz).abs());
        max_pos = max_pos.max(d);
        assert!(d <= POS_TOL, "tick {i}: player pos diverged by {d}");
        assert_eq!(driver.score, want.score, "tick {i}: score");
        assert_eq!(driver.vy, want.vy, "tick {i}: vertical velocity");
        assert_eq!(driver.dead as u32, 1 - want.alive, "tick {i}: alive flag");
        let mobs_alive = driver.mobs.iter().filter(|m| m.alive).count() as u32;
        assert_eq!(mobs_alive, want.mobs_alive, "tick {i}: mobs_alive");
    }

    // Exact event sequence.
    assert_eq!(events.len(), doc.events.len(), "event count");
    for ((t, got), want) in events.iter().zip(doc.events.iter()) {
        let kind = match got {
            SquashEvent::Spawned { .. } => "spawn",
            SquashEvent::Squashed { .. } => "squash",
            SquashEvent::PlayerDied => "death",
            SquashEvent::Despawned { .. } => "despawn",
        };
        assert_eq!(*t, want.t, "event tick: {got:?} vs {want:?}");
        assert_eq!(kind, want.kind, "event kind @{t}");
        match (got, want.kind.as_str()) {
            (SquashEvent::Spawned { index, .. }, "spawn")
            | (SquashEvent::Despawned { index }, "despawn") => {
                assert_eq!(*index, want.index.unwrap(), "event index @{t}");
            }
            (SquashEvent::Squashed { index, score }, "squash") => {
                assert_eq!(*index, want.index.unwrap(), "squash index @{t}");
                assert_eq!(*score, want.score.unwrap(), "squash score @{t}");
            }
            (SquashEvent::PlayerDied, "death") => {}
            _ => panic!("event mismatch @{t}: {got:?} vs {want:?}"),
        }
    }

    // Scenario shape: exactly 3 squashes then exactly 1 death, squashes first.
    let squashes: Vec<u64> = events
        .iter()
        .filter(|(_, e)| matches!(e, SquashEvent::Squashed { .. }))
        .map(|(t, _)| *t)
        .collect();
    let deaths: Vec<u64> = events
        .iter()
        .filter(|(_, e)| matches!(e, SquashEvent::PlayerDied))
        .map(|(t, _)| *t)
        .collect();
    assert_eq!(squashes.len(), 3, "scripted scenario: 3 squashes");
    assert_eq!(deaths.len(), 1, "scripted scenario: 1 death");
    assert!(
        squashes.iter().all(|t| *t < deaths[0]),
        "squashes precede death"
    );
    eprintln!(
        "golden trace: {} ticks, max pos diff {max_pos:e}",
        doc.actions.len()
    );
}

#[test]
fn spawn_stream_reproducible_across_runtimes() {
    let doc = load_trace();
    let run = || {
        let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
        let mut driver = SquashDriver::new(SQUASH_SEED);
        let mut spawns = Vec::new();
        for a in doc.actions.iter().take(1200) {
            for e in rt.step(&mut driver, vec![action_of(*a)]) {
                if let SquashEvent::Spawned {
                    pos, yaw, speed, ..
                } = e.payload
                {
                    spawns.push((pos, yaw, speed));
                }
            }
        }
        spawns
    };
    let a = run();
    let b = run();
    assert_eq!(a, b, "same seed ⇒ identical spawn stream");
    assert!(!a.is_empty());
    // Matches the frozen recorded tuples.
    for (i, (got, want)) in a.iter().zip(doc.spawns.iter()).enumerate() {
        assert_eq!(i as u32, want.index, "spawn order == frozen index");
        assert_eq!(got.2, want.speed, "spawn speed");
        assert!((got.0.x - want.pos[0]).abs() < 1e-4, "spawn x");
        assert!((got.0.z - want.pos[2]).abs() < 1e-4, "spawn z");
        assert!((got.0.y - want.pos[1]).abs() < 1e-4, "spawn y");
        assert!((got.1 - want.yaw).abs() < 1e-4, "spawn yaw");
    }
    // velocity parity with the frozen tuples
    for (got, want) in a.iter().zip(doc.spawns.iter()) {
        let want_vel = glam::Vec3::new(-got.2 * want.yaw.sin(), 0.0, -got.2 * want.yaw.cos());
        let _ = want_vel;
        let vx = -got.2 * got.1.sin();
        let vz = -got.2 * got.1.cos();
        assert!((vx - want.vel[0]).abs() < 1e-3, "spawn vel x");
        assert!((vz - want.vel[1]).abs() < 1e-3, "spawn vel z");
    }
    // frozen spawn ticks: 60, 120, 180, ... at 120 Hz
    for (i, want) in doc.spawns.iter().enumerate() {
        assert_eq!(want.tick, 60 * (i as u64 + 1), "frozen spawn cadence");
    }
    // Different seed ⇒ different stream.
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED ^ 0xFF);
    let mut other = SquashDriver::new(SQUASH_SEED ^ 0xFF);
    let first_spawn = (0..120)
        .find_map(|_| {
            for e in rt.step(&mut other, vec![SquashAction::default()]) {
                if let SquashEvent::Spawned { pos, .. } = e.payload {
                    return Some(pos);
                }
            }
            None
        })
        .unwrap();
    assert!(a.first().map(|(p, _, _)| *p) != Some(first_spawn));
}

#[test]
fn squash_scores_exactly_once_per_mob() {
    let doc = load_trace();
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut driver = SquashDriver::new(SQUASH_SEED);
    let mut squashed_indices = Vec::new();
    let mut score_events = Vec::new();
    for a in doc.actions.iter() {
        for e in rt.step(&mut driver, vec![action_of(*a)]) {
            match e.payload {
                SquashEvent::Squashed { index, score } => {
                    squashed_indices.push(index);
                    score_events.push(score);
                }
                _ => {}
            }
        }
    }
    let unique: std::collections::HashSet<_> = squashed_indices.iter().collect();
    assert_eq!(
        unique.len(),
        squashed_indices.len(),
        "no mob squashed twice"
    );
    // Score increments by exactly 1 per squash.
    let mut expected = 1;
    for s in &score_events {
        assert_eq!(*s, expected, "score increments once per squash");
        expected += 1;
    }
    assert_eq!(driver.score as usize, squashed_indices.len());
}

#[test]
fn death_stops_spawning_and_shows_retry_overlay() {
    let doc = load_trace();
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut driver = SquashDriver::new(SQUASH_SEED);
    let death_tick = doc
        .events
        .iter()
        .find(|e| e.kind == "death")
        .map(|e| e.t)
        .unwrap();
    let mut post_death_spawns = 0u32;
    for (i, a) in doc.actions.iter().enumerate() {
        for e in rt.step(&mut driver, vec![action_of(*a)]) {
            if matches!(e.payload, SquashEvent::Spawned { .. }) && i as u64 > death_tick {
                post_death_spawns += 1;
            }
        }
    }
    assert_eq!(
        post_death_spawns, 0,
        "MobTimer stops on hit (Main.gd 45-47)"
    );
    assert!(driver.dead);
    assert!(driver.retry_visible, "Retry overlay visible after hit");
    // Mobs keep draining after death (world keeps running).
    let last = doc.ticks_trace.last().unwrap();
    assert!(
        last.mobs_alive < 6,
        "mobs despawn after death: {}",
        last.mobs_alive
    );
}

#[test]
fn retry_reset_isolation_reproduces_prefix() {
    let doc = load_trace();
    let prefix = 300usize;
    let run_prefix = || {
        let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
        let mut driver = SquashDriver::new(SQUASH_SEED);
        let session = rt.session();
        let mut trace = Vec::new();
        for a in doc.actions.iter().take(prefix) {
            let events = rt.step(&mut driver, vec![action_of(*a)]);
            assert!(events.iter().all(|e| e.session == session));
            trace.push((driver.player, driver.score));
        }
        (session, trace)
    };
    let (s1, t1) = run_prefix();
    // Retry = host reset: new session, no stale state, identical replay.
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut driver = SquashDriver::new(SQUASH_SEED);
    for a in doc.actions.iter().take(60) {
        let _ = rt.step(&mut driver, vec![action_of(*a)]);
    }
    rt.reset(SQUASH_SEED);
    driver.reset();
    assert!(rt.tick() == 0 && rt.scene().live_count() == 0);
    let (s2, t2) = {
        let session = rt.session();
        let mut trace = Vec::new();
        for a in doc.actions.iter().take(prefix) {
            let events = rt.step(&mut driver, vec![action_of(*a)]);
            assert!(events.iter().all(|e| e.session == session));
            trace.push((driver.player, driver.score));
        }
        (session, trace)
    };
    assert_ne!(s1, s2, "retry mints a new session");
    assert_eq!(t1, t2, "same seed + stream after retry reproduces the run");
}

#[test]
fn counterexample_no_jumps_never_squashes() {
    // Same seed and stream shape but jumps stripped: the player must die
    // WITHOUT any squash (proves the jump actions drive the squashes and the
    // detector is not vacuous).
    let doc = load_trace();
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut driver = SquashDriver::new(SQUASH_SEED);
    let mut squashes = 0u32;
    let mut death: Option<u64> = None;
    for (i, a) in doc.actions.iter().enumerate() {
        let mut action = action_of(*a);
        action.jump = false;
        for e in rt.step(&mut driver, vec![action]) {
            match e.payload {
                SquashEvent::Squashed { .. } => squashes += 1,
                SquashEvent::PlayerDied => death = Some(i as u64),
                _ => {}
            }
        }
        if death.is_some() {
            break;
        }
    }
    assert_eq!(squashes, 0, "no jumps ⇒ no squashes");
    assert!(death.is_some(), "standing player is eventually hit");
}

