// Review r1 repairs: F03 (source-state paths) + F11 (shared 3D contract)
// ---------------------------------------------------------------------------

use agp::core::scene::{SceneChange, Transform};
use agp::games::squash::{detector_fatal, project_instances, EntityKind, LiveKey, LiveSquashInput};
use agp::render3d::collision::{
    sphere_vs_obb, MOB_BOX_HALF, MOB_BOX_OFFSET_Y, PLAYER_SPHERE_RADIUS,
};

/// F03a: spawn aim targets the player's ACTUAL position (Main.gd line 36) —
/// a moving player changes the spawn yaw (review measured identical yaws for
/// stationary vs moving players before the repair).
#[test]
fn f03_spawn_aim_tracks_the_actual_player_position() {
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut d1 = SquashDriver::new(SQUASH_SEED);
    let mut yaw_stationary = None;
    for _ in 0..61 {
        for e in rt.step(&mut d1, vec![SquashAction::default()]) {
            if let SquashEvent::Spawned { yaw, .. } = e.payload {
                yaw_stationary = Some(yaw);
            }
        }
    }
    let yaw_stationary = yaw_stationary.expect("a spawn happened by tick 60");

    // moving player: hold move_right through the first spawn
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut d2 = SquashDriver::new(SQUASH_SEED);
    let mut yaw_moving = None;
    let hold = SquashAction {
        move_x: 1,
        move_z: 0,
        jump: false,
        retry: false,
        reset: false,
    };
    for _ in 0..61 {
        for e in rt.step(&mut d2, vec![hold]) {
            if let SquashEvent::Spawned { yaw, .. } = e.payload {
                yaw_moving = Some(yaw);
            }
        }
    }
    let yaw_moving = yaw_moving.expect("a spawn happened by tick 60");
    assert!(
        d2.player.x > 5.0,
        "the moving player actually moved: {}",
        d2.player.x
    );
    assert_ne!(
        yaw_stationary, yaw_moving,
        "spawn yaw must change when the player is moving (F03)"
    );
}

/// F03b: the MobDetector Area3D channel (Player.tscn lines 63–83) is fatal
/// even when the body sphere does not touch the mob box — the review probe
/// geometry, asserted both ways plus facing rotation.
#[test]
fn f03_detector_channel_fatal_without_body_contact() {
    let player = glam::Vec3::new(0.0, 0.792278, 0.0);
    // review probe: mob at (0.716365, 1, 2.1), velocity along -z (yaw 0)
    let mob = glam::Vec3::new(0.716365, 1.0, 2.1);
    let mob_vel = glam::Vec3::new(0.0, 0.0, -14.0);
    let mob_yaw = (-mob_vel.x).atan2(-mob_vel.z);
    let box_center = mob + glam::Vec3::new(0.0, MOB_BOX_OFFSET_Y, 0.0);
    let body = sphere_vs_obb(
        player,
        PLAYER_SPHERE_RADIUS,
        box_center,
        MOB_BOX_HALF,
        mob_yaw,
    );
    assert!(body.is_none(), "review probe: no body contact");
    assert!(
        detector_fatal(player, 0.0, mob, mob_yaw),
        "detector overlap must be fatal without body contact (F03)"
    );
    // far mob: no channel fires
    let far = glam::Vec3::new(10.0, 1.0, 10.0);
    assert!(!detector_fatal(player, 0.0, far, 0.0));
    // facing rotation swings the cylinders away
    assert!(!detector_fatal(player, std::f32::consts::PI, mob, mob_yaw));
}

/// F829-R4-03: detector classification must be invariant under a GLOBAL
/// rigid rotation of the encounter (player + mob + both yaws rotated by the
/// same angle). The previous frame math applied the mob's world yaw to a
/// player-local offset, so rotating both bodies changed the outcome. The
/// bound probe from the review: player at origin facing 0, mob
/// (-2, .5, -.7) yaw 0; rotated 90°: facing π/2, mob (-.7, .5, 2), yaw π/2
/// — identical classification, and both are body-contact-negative.
#[test]
fn r4_detector_classification_rigid_rotation_invariant() {
    let rotate = |yaw: f32, v: glam::Vec3| glam::Mat4::from_rotation_y(yaw).transform_vector3(v);
    // Body contact must be negative for the bound probe (both orientations).
    let body_neg = |player: glam::Vec3, mob: glam::Vec3, mob_yaw: f32| {
        let box_center = mob + glam::Vec3::new(0.0, MOB_BOX_OFFSET_Y, 0.0);
        sphere_vs_obb(
            player,
            PLAYER_SPHERE_RADIUS,
            box_center,
            MOB_BOX_HALF,
            mob_yaw,
        )
        .is_none()
    };
    // Encounters defined in the player-local frame: (mob offset, mob yaw
    // relative to facing, expect_fatal, expect_body_free). Coordinates are
    // NOT tuned to the implementation — they reuse the frozen probe
    // geometry (F03) and simple near/far variants of the frozen detector
    // cylinder positions.
    let encounters: [(glam::Vec3, f32, bool, bool); 4] = [
        // bound-probe miss geometry (body-free detector negative)
        (glam::Vec3::new(-2.0, 0.5, -0.7), 0.0, false, true),
        // frozen F03 probe geometry (body-free detector HIT): mob at
        // (0.716365, 1, 2.1) relative to the resting player.
        (
            glam::Vec3::new(0.716365, 1.0 - 0.792278, 2.1),
            0.0,
            true,
            true,
        ),
        // small-cylinder corner hit (detector small[0] at (0.455, .95, 1.142))
        (
            glam::Vec3::new(0.455268, 0.95 - 0.792278, 1.1423 + 0.30),
            0.0,
            true,
            false,
        ),
        // y-channel miss: same xz as the frozen F03 hit but the mob is
        // airborne above the detector band (jump-over geometry).
        (
            glam::Vec3::new(0.716365, 2.0 - 0.792278, 2.1),
            0.0,
            false,
            true,
        ),
    ];
    // Global rotations to apply to each encounter (radians around +Y).
    let globals: [f32; 5] = [
        0.0,
        std::f32::consts::FRAC_PI_2,
        std::f32::consts::PI,
        -1.1,
        2.5,
    ];
    let player_rest = glam::Vec3::new(0.0, 0.792278, 0.0);
    for (offset, rel_yaw, expect_fatal, expect_body_free) in encounters {
        for g in globals {
            let facing = g;
            let mob = player_rest + rotate(g, offset);
            let mob_yaw = g + rel_yaw;
            if expect_body_free {
                assert!(
                    body_neg(player_rest, mob, mob_yaw),
                    "bound probe must stay body-contact-negative (g={g})"
                );
            }
            let got = detector_fatal(player_rest, facing, mob, mob_yaw);
            assert_eq!(
                got, expect_fatal,
                "rigid rotation g={g} changed detector classification (offset={offset:?}, rel_yaw={rel_yaw})"
            );
            // The identical encounter rebuilt with facing=0 must classify
            // the same (relative geometry is all that matters).
            let base = detector_fatal(player_rest, 0.0, player_rest + offset, rel_yaw);
            assert_eq!(got, base, "classification depends on absolute orientation");
        }
    }
}

/// F03c: facing/animation source states — movement facing yaw, speed-scale
/// clock (4 moving / 1 idle), spawn-age-based mob animation, jump pitch.
#[test]
fn f03_facing_and_animation_states_match_player_gd() {
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut driver = SquashDriver::new(SQUASH_SEED);
    for _ in 0..10 {
        let _ = rt.step(&mut driver, vec![SquashAction::default()]);
    }
    let idle_anim = driver.anim_time;
    assert!(
        (idle_anim - 10.0 * (1.0 / 120.0)).abs() < 1e-6,
        "idle advances 1x"
    );
    assert!(!driver.moving);

    let action = SquashAction {
        move_x: 1,
        move_z: 0,
        jump: false,
        retry: false,
        reset: false,
    };
    for _ in 0..10 {
        let _ = rt.step(&mut driver, vec![action]);
    }
    assert!(driver.moving);
    assert_eq!(
        driver.facing_yaw,
        (-14.0f32).atan2(0.0),
        "Basis.looking_at(+x)"
    );
    assert!(
        (driver.anim_time - idle_anim - 10.0 * (1.0 / 120.0) * 4.0).abs() < 1e-5,
        "moving advances 4x (Player.gd line 31)"
    );

    // jump pitch: rotation.x = PI/6 * vy / jump_impulse (Player.gd line 66)
    let mut vy_mid = 0.0f32;
    for _ in 0..600 {
        let action = SquashAction {
            move_x: 0,
            move_z: 0,
            jump: true,
            retry: false,
            reset: false,
        };
        let _ = rt.step(&mut driver, vec![action]);
        if driver.player.y > PLAYER_SPHERE_RADIUS + 0.5 {
            vy_mid = driver.vy;
            break;
        }
    }
    assert!(vy_mid > 0.0, "mid-jump vertical velocity");
    let (_scale, rot, _t) = agp::games::squash::player_model_matrix(
        driver.player,
        driver.facing_yaw,
        vy_mid,
        driver.anim_time,
    )
    .to_scale_rotation_translation();
    let pitch = rot.to_euler(glam::EulerRot::YXZ).1;
    // the node carries PI/6 * vy / jump_impulse (Player.gd line 66) PLUS the
    // Character child's bob rotation on the same axis (additive composition).
    let (_, bob_rot) = agp::render3d::BobAnimation::default().eval(driver.anim_time);
    let expected = std::f32::consts::FRAC_PI_6 * vy_mid / 20.0 + bob_rot;
    assert!(
        (pitch - expected).abs() < 1e-3,
        "rotation.x = PI/6 * vy / jump_impulse + bob: {pitch} vs {expected}"
    );

    // mob animation phase = age since spawn (not global time)
    let ages: Vec<f32> = driver
        .mobs
        .iter()
        .filter(|m| m.alive)
        .map(|m| m.age)
        .collect();
    if ages.len() >= 2 {
        assert!(
            (ages[0] - ages[1]).abs() > 1e-6,
            "mob animation phase = age since spawn"
        );
    }
}

/// F01: the live-input state machine (real keyboard path) — press edges,
/// held-key behavior, dead gating. (Interactive verification: run
/// `--replay live`, tap Space = one jump, hold Space = one jump until
/// re-press, idle = no auto-jump.)
#[test]
fn f01_live_input_press_edge_semantics() {
    let mut input = LiveSquashInput::default();
    for _ in 0..5 {
        assert!(!input.action(false).jump, "F01: idle never jumps");
    }
    input.key_event(LiveKey::Space, true, false);
    assert!(input.action(false).jump, "F01: press edge = one jump");
    for _ in 0..5 {
        assert!(
            !input.action(false).jump,
            "F01: held Space does not re-fire"
        );
    }
    input.key_event(LiveKey::Space, false, false);
    input.key_event(LiveKey::Space, true, false);
    assert!(input.action(false).jump, "F01: re-press fires again");

    // airborne: the frozen sim ignores jump unless grounded
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut driver = SquashDriver::new(SQUASH_SEED);
    let a = SquashAction {
        move_x: 0,
        move_z: 0,
        jump: true,
        retry: false,
        reset: false,
    };
    let _ = rt.step(&mut driver, vec![a]);
    assert!(driver.player.y > PLAYER_SPHERE_RADIUS, "jumped");
    let before = driver.vy;
    let _ = rt.step(
        &mut driver,
        vec![SquashAction {
            move_x: 0,
            move_z: 0,
            jump: true,
            retry: false,
            reset: false,
        }],
    );
    assert_eq!(
        driver.vy,
        before - 75.0 / 120.0,
        "airborne jump edge ignored (not grounded)"
    );

    // dead: no jump
    let mut input = LiveSquashInput::default();
    input.key_event(LiveKey::Space, true, false);
    assert!(!input.action(true).jump, "F01: dead player cannot jump");
}

/// F02: the live elapsed-time accumulator is cadence-invariant (unit level;
/// the windowed hosts wire the same TickClock::feed_capped).
#[test]
fn f02_live_tick_accumulator_cadence_invariant() {
    let dt = Duration::from_nanos(8_333_333);
    let total = Duration::from_millis(500);
    let mut counts = Vec::new();
    for slices in [30u32, 60, 120] {
        let mut clock = agp::core::TickClock::new(dt);
        let per = total / slices;
        let mut n = 0u64;
        for _ in 0..slices {
            n += clock.feed_capped(per, 8);
        }
        counts.push(n);
    }
    assert!(
        counts.iter().max().unwrap() - counts.iter().min().unwrap() <= 1,
        "F02: same elapsed ⇒ same ticks at any redraw cadence: {counts:?}"
    );
    // overload protection: a burst is capped, the debt is dropped
    let mut clock = agp::core::TickClock::new(dt);
    assert_eq!(clock.feed_capped(Duration::from_millis(500), 8), 8);
    assert_eq!(clock.feed_capped(dt, 8), 1, "no spiral of debt");
}

/// F11: an independent consumer replays the ChangeLog into a fresh runtime
/// and reconstructs the actual 3D scene; edits via shared IDs are visible
/// in the projection; stale (pre-reset) IDs are rejected.
#[test]
fn f11_shared_contract_reconstructs_and_edits_3d_scene() {
    let doc = load_trace();
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut driver = SquashDriver::new(SQUASH_SEED);
    let mut squashed_index = None;
    for a in doc.actions.iter().take(600) {
        for e in rt.step(&mut driver, vec![action_of(*a)]) {
            if let SquashEvent::Squashed { index, .. } = e.payload {
                squashed_index = Some(index);
            }
        }
    }
    let live_mobs = driver.mobs.iter().filter(|m| m.alive).count();
    // the shared scene mirrors the world (player + live mobs)
    assert_eq!(
        rt.scene().live_count(),
        1 + live_mobs,
        "F11: real scene objects"
    );
    assert!(driver.player_object_id().is_some());
    assert!(
        driver
            .mobs
            .first()
            .map(|m| driver.mob_object_id(m.index))
            .is_some(),
        "live mobs keep shared ids; pruned dead ones drop them"
    );

    // 1) replay the ChangeLog into a fresh runtime: same scene, and the
    //    projected player position matches the driver's world.
    let replayed = rt.log().replay();
    assert_eq!(replayed.live_count(), rt.scene().live_count());
    let projected = project_instances(&replayed);
    let (_id, kind, mat) = projected
        .iter()
        .find(|(id, _, _)| Some(*id) == driver.player_object_id())
        .expect("player object present after log replay");
    assert_eq!(*kind, EntityKind::Player);
    assert!(
        (mat.w_axis.x - driver.player.x).abs() < 1e-3
            && (mat.w_axis.z - driver.player.z).abs() < 1e-3,
        "reconstructed player position matches the world"
    );

    // 2) edit one live mob through the shared ID: rendering-observable.
    let live_mob = driver.mobs.iter().find(|m| m.alive).expect("a live mob");
    let mob_id = driver.mob_object_id(live_mob.index).unwrap();
    let moved = Transform {
        translation: glam::Vec3::new(3.25, 1.0, -2.5),
        ..Default::default()
    };
    let errs = rt.submit(&[SceneChange::SetTransform(mob_id, moved)]);
    assert!(errs.is_empty(), "shared edit accepted");
    let now = project_instances(rt.scene());
    let (_, kind, mat) = now
        .iter()
        .find(|(id, _, _)| *id == mob_id)
        .expect("edited mob present");
    assert_eq!(*kind, EntityKind::Mob);
    assert!(
        (mat.w_axis.x - 3.25).abs() < 1e-4 && (mat.w_axis.z + 2.5).abs() < 1e-4,
        "rendering-observable edit through the shared contract"
    );

    // 3) stale update across restart: old-session ID rejected, scene empty.
    rt.reset(SQUASH_SEED);
    let errs = rt.submit(&[SceneChange::SetTransform(mob_id, moved)]);
    assert_eq!(errs.len(), 1, "stale pre-reset ID rejected");
    assert_eq!(rt.scene().live_count(), 0, "new session starts empty");

    // squashed/despawned mobs are pruned from the driver AND destroyed in
    // the shared scene — the log replay's object count already proves both
    // (replayed.live_count() == live scene count, asserted above).
    let _ = squashed_index;
}

/// F829-R4-01: player role identity is the session's first-spawned id and
/// must be stable through death, mob despawn, empty scene and restart. The
/// old projection classified the first ALIVE object as Player, so after the
/// player's destruction a surviving mob rendered with player meshes, and
/// the classification changed again as leading mobs despawned (bound
/// input: canonical trace stepped past the death tick — player id
/// (index0,generation0) invalid, live mobs must ALL project as Mob).
#[test]
fn r4_player_role_identity_stable_through_death_and_reuse() {
    let doc = load_trace();
    let mut rt = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
    let mut driver = SquashDriver::new(SQUASH_SEED);
    let old_player = loop {
        if driver.dead {
            break driver.player_object_id().expect("player was spawned");
        }
        let a = doc
            .actions
            .get(driver.step_count() as usize)
            .copied()
            .expect("trace covers the death");
        let _ = rt.step(&mut driver, vec![action_of(a)]);
        assert!(
            driver.step_count() <= doc.actions.len() as u64,
            "death must occur within the frozen trace"
        );
    };
    // bound-probe shape: the player is the session's first spawn.
    assert_eq!(old_player.index(), 0);
    assert_eq!(old_player.generation(), 0);
    assert_eq!(rt.scene().first_spawned(), Some(old_player));
    // the destroyed player identity is no longer valid in the scene.
    assert!(rt.scene().validate_id(old_player).is_err());

    // after death with live mobs: EVERY projected entity is a Mob.
    let live_mobs = driver.mobs.iter().filter(|m| m.alive).count();
    assert!(live_mobs > 0, "death leaves a living mob population");
    let projected = project_instances(rt.scene());
    assert_eq!(projected.len(), live_mobs, "only mobs remain in the scene");
    assert!(
        projected
            .iter()
            .all(|(_, kind, _)| *kind == EntityKind::Mob),
        "no live id may equal the dead first-spawned player identity"
    );

    // leading-mob deletion sequence: classification stays Mob as the
    // population shrinks; ids keep their kind step over step.
    let mut prev_kinds: std::collections::HashMap<_, _> =
        projected.iter().map(|(id, kind, _)| (*id, *kind)).collect();
    let mut guard = 0u32;
    while driver.mobs.iter().any(|m| m.alive) && guard < 10_000 {
        let a = doc
            .actions
            .get(driver.step_count() as usize)
            .copied()
            .unwrap_or_default();
        let _ = rt.step(&mut driver, vec![action_of(a)]);
        guard += 1;
        let now = project_instances(rt.scene());
        for (id, kind, _) in &now {
            assert_eq!(*kind, EntityKind::Mob, "kind flips as mobs despawn");
            if let Some(prev) = prev_kinds.get(id) {
                assert_eq!(prev, kind, "kind changed for a surviving id");
            }
        }
        prev_kinds = now.iter().map(|(id, kind, _)| (*id, *kind)).collect();
    }

    // empty scene: nothing projects; the anchor id is inert.
    assert_eq!(rt.scene().live_count(), 0);
    assert!(project_instances(rt.scene()).is_empty());
    assert_eq!(rt.scene().first_spawned(), Some(old_player));

    // independent-log-replay classification: replaying the same change log
    // reproduces the same per-id kinds (player during life, all Mob after).
    let replayed = rt.log().replay();
    assert_eq!(replayed.live_count(), 0);
    let life_log = {
        // replay a pre-death prefix: first spawned id classifies Player.
        let mut rt2 = Runtime::new(Duration::from_nanos(8_333_333), SQUASH_SEED);
        let mut d2 = SquashDriver::new(SQUASH_SEED);
        for _ in 0..60 {
            let _ = rt2.step(&mut d2, vec![action_of(doc.actions[0])]);
        }
        rt2.log().replay()
    };
    let kinds: Vec<_> = project_instances(&life_log)
        .iter()
        .map(|(_, kind, _)| *kind)
        .collect();
    assert_eq!(
        kinds.iter().filter(|k| **k == EntityKind::Player).count(),
        1
    );
    // session ids are process-unique by design and never part of the
    // replay-equality contract — compare identity by index+generation.
    let replay_anchor = life_log.first_spawned().expect("replay has an anchor");
    assert_eq!(replay_anchor.index(), old_player.index());
    assert_eq!(replay_anchor.generation(), old_player.generation());

    // restart: fresh session, new first spawn is the new player.
    rt.reset(SQUASH_SEED);
    driver.reset();
    let _ = rt.step(&mut driver, vec![action_of(doc.actions[0])]);
    let new_player = driver
        .player_object_id()
        .expect("new session spawns a player");
    assert_ne!(new_player, old_player, "restart mints a fresh identity");
    assert_eq!(rt.scene().first_spawned(), Some(new_player));
    let kinds: Vec<_> = project_instances(rt.scene())
        .iter()
        .map(|(_, kind, _)| *kind)
        .collect();
    assert_eq!(
        kinds.iter().filter(|k| **k == EntityKind::Player).count(),
        1
    );
}

/// F829-R4-02: Space restarts the failed LIVE game through the real host
/// mapping (frozen ui_accept promise: "Space or Enter"). Covers the dead
/// Space retry, the dead Enter retry, living Space = jump only, retry
/// visibility gating, and the first input after reload — the sibling of the
/// F01 jump-edge fix that the r1 repair missed.
#[test]
fn r4_dead_space_and_enter_retry_through_host_mapping() {
    // The host consumes LiveEffect::RetryPressed only while
    // dead && retry_visible — model that gate exactly.
    let host_gate = |dead: bool, retry_visible: bool, effect: Option<LiveEffect>| -> bool {
        effect.is_some() && dead && retry_visible
    };
    let mut input = LiveSquashInput::default();

    // dead Space -> retry effect; the driver would reload.
    assert!(host_gate(
        true,
        true,
        input.key_event(LiveKey::Space, true, true)
    ));
    // no stale jump edge armed for the first tick after the reload.
    assert!(
        !input.action(false).jump,
        "first tick after reload must not jump"
    );
    // held Space through the reload: still held, no new edge.
    assert_eq!(input.key_event(LiveKey::Space, true, false), None);
    assert!(!input.action(false).jump);

    // dead Enter -> retry effect.
    let mut input = LiveSquashInput::default();
    assert!(host_gate(
        true,
        true,
        input.key_event(LiveKey::Enter, true, true)
    ));

    // retry VISIBILITY gating: an effect can never reload a living game.
    let mut input = LiveSquashInput::default();
    let effect = input.key_event(LiveKey::Space, true, true);
    assert!(!host_gate(false, true, effect), "alive: no reload");
    let mut input = LiveSquashInput::default();
    let effect = input.key_event(LiveKey::Enter, true, true);
    assert!(
        !host_gate(true, false, effect),
        "retry not visible: no reload"
    );

    // living Space = jump edge only, never a retry effect.
    let mut input = LiveSquashInput::default();
    assert_eq!(input.key_event(LiveKey::Space, true, false), None);
    assert!(input.action(false).jump);
    // living Enter = nothing at all (machine-level sibling audit).
    let mut input = LiveSquashInput::default();
    assert_eq!(input.key_event(LiveKey::Enter, true, false), None);
    assert!(!input.take_retry_edge());
}
